command:
/**
 * Solo DarkSpace Oracle
 * Quick inspiration for solo play or GM improvisation.
 */
const pack = game.packs.get("darkspace.rollable-tables");
if (!pack) {
  ui.notifications.error("DarkSpace rollable-tables pack not found.");
} else {
  const dangerTable = await pack.getDocument("dsTabOracDanger");
  const qualityTable = await pack.getDocument("dsTabOracQuality");
  const reactionTable = await pack.getDocument("dsTabOracReaction");

  const danger = (await dangerTable?.draw({ displayChat: false }))?.results[0]?.text || "Standard";
  const quality = (await qualityTable?.draw({ displayChat: false }))?.results[0]?.text || "Neutral";
  const reaction = (await reactionTable?.draw({ displayChat: false }))?.results[0]?.text || "Wary";

  const content = `
    <div style="border: 1px solid #ab47bc; background: rgba(25, 10, 30, 0.95); color: #f3e5f5; padding: 12px; border-radius: 6px;">
      <h3 style="margin: 0 0 8px 0; color: #ce93d8; border-bottom: 1px solid #ab47bc; padding-bottom: 4px;">
        <i class="fas fa-dice-d20"></i> SoloDark Oracle
      </h3>
      <table style="width: 100%; border: none;">
        <tr><td style="width: 35%; color: #e1bee7;"><b>Danger Level:</b></td><td>${danger}</td></tr>
        <tr><td style="color: #e1bee7;"><b>Vibe / Tone:</b></td><td>${quality}</td></tr>
        <tr><td style="color: #e1bee7;"><b>NPC Reaction:</b></td><td>${reaction}</td></tr>
      </table>
    </div>
  `;

  await ChatMessage.create({
    user: game.user._id,
    speaker: { alias: "SoloDark Oracle" },
    content: content
  });
}
